/* @lc app=leetcode id=2127 lang=kotlin */
class Solution { fun maximumInvitations(favorite: IntArray): Int = favorite.size.let { n -> IntArray(n).apply { favorite.forEach { this[it]++ } }.let { inDegree -> IntArray(n).let { chainLen -> IntArray(n).let { q -> intArrayOf(0, 0).let { ptr -> (0 until n).filter { inDegree[it] == 0 }.forEach { q[ptr[1]++] = it }.run { generateSequence { if (ptr[0] < ptr[1]) q[ptr[0]++] else null }.forEach { u -> favorite[u].let { v -> maxOf(chainLen[v], chainLen[u] + 1).also { chainLen[v] = it }.run { if (--inDegree[v] == 0) v.also { q[ptr[1]++] = it } } } } } } }.run { intArrayOf(0, 0).let { res -> (0 until n).filter { inDegree[it] > 0 }.forEach { i -> generateSequence(i) { favorite[it] }.takeWhile { inDegree[it] > 0 }.onEach { inDegree[it] = 0 }.toList().let { cycle -> if (cycle.size == 2) (res[1] + 2 + chainLen[cycle[0]] + chainLen[cycle[1]]).also { res[1] = it } else maxOf(res[0], cycle.size).also { res[0] = it } } }.run { maxOf(res[0], res[1]) } } } } } }